// A scripted Veld plugin (protocol 1) for the CLI tests. Zero dependencies.
// Usage: node stub_plugin.mjs --mode ok|crash|escape|noisy [--caps a,b] [--roles client,server]
import { createInterface } from "node:readline";

const args = process.argv.slice(2);
const opt = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : fallback;
};
const mode = opt("--mode", "ok");
const caps = opt("--caps", "constraints").split(",").filter(Boolean);
const roles = opt("--roles", "client,server").split(",");

const send = (v) => process.stdout.write(JSON.stringify(v) + "\n");
console.error(`stub starting in mode ${mode}`);

const rl = createInterface({ input: process.stdin });
const lines = [];
let waiting = null;
rl.on("line", (l) => (waiting ? waiting(l) : lines.push(l)));
rl.on("close", () => process.exit(0));
const next = () => new Promise((res) => (lines.length ? res(lines.shift()) : (waiting = (l) => ((waiting = null), res(l)))));

function files(ir) {
  const out = [];
  for (const d of ir.decls) out.push({ path: `types/${d.qualified.replace(/[:/]/g, "_")}.txt`, content: d.sig });
  for (const s of ir.services) for (const e of s.endpoints) out.push({ path: `ops/${e.sig.replace(/[:/@]/g, "_")}.txt`, content: e.sig });
  out.push({ path: "plugin-output.txt", content: `generated by the stub, mode ${mode}\n` });
  return out;
}

await next();
send({ type: "hello", protocol: "1", name: "stub", version: "1.0.0", roles, capabilities: caps });
const generate = JSON.parse(await next());
if (mode === "crash") process.exit(3);
const list = mode === "escape" ? [{ path: "../escaped.txt", content: "x" }] : files(generate.ir);
send({ type: "result", files: list, diagnostics: [] });
process.exit(0);
